"""Generated production-key authority in a disposable qualification store.

The concrete bootstrap/read/lock APIs are shared by pinned baseline 2e672d2
and the candidate. This is fixture provisioning, not interactive enrollment.
"""

from __future__ import annotations

from codex_plugin_scanner.guard.runtime.command_extensions import BUILT_IN_COMMAND_EXTENSION_REGISTRY
from codex_plugin_scanner.guard.runtime.extension_control_authority import (
    AuthorityHealth,
    ExtensionControlAuthorityView,
)
from codex_plugin_scanner.guard.store import GuardStore
from codex_plugin_scanner.guard.store_base import EncryptedFileSecretStore


def verify_empty_command_authority(store: GuardStore) -> dict[str, str]:
    view = store.read_extension_control_authority(catalog_digest=BUILT_IN_COMMAND_EXTENSION_REGISTRY.catalog_digest)
    return _verified_empty_view(view)


def _verified_empty_view(view: ExtensionControlAuthorityView) -> dict[str, str]:
    if view.health is not AuthorityHealth.PROTECTED or view.revision != 0 or view.layers:
        raise RuntimeError("qualification command authority is not verified empty protected state")
    return {
        "provisioning": "isolated_ci_generated_key_empty_authority",
        "enrollment_flow": "not_exercised",
        "verified_health": view.health.value,
    }


def prepare_empty_command_authority(store: GuardStore) -> dict[str, str]:
    store._extension_control_authority_secret_store = EncryptedFileSecretStore(store.guard_home)
    catalog = BUILT_IN_COMMAND_EXTENSION_REGISTRY.catalog_digest
    with store._extension_control_authority_lock():
        # The pinned baseline lock is not reentrant. Both releases expose the
        # concrete locked reader, so keep the entire bootstrap interval under
        # one real lease without calling the public lock-taking reader again.
        current = store._read_extension_control_authority_locked(catalog)
        if current.health is not AuthorityHealth.UNENROLLED:
            raise RuntimeError("qualification command authority must be freshly unenrolled")
        store._bootstrap_extension_control_authority(catalog, key=None)
        return _verified_empty_view(store._read_extension_control_authority_locked(catalog))

"""Shared containment helpers for Guard daemon startup failures."""

from __future__ import annotations

import logging
import sqlite3
import threading
import time
from typing import TYPE_CHECKING

_LOGGER = logging.getLogger(__name__)

if TYPE_CHECKING:
    from .server import GuardDaemonServer


def startup_generation_is_current(server: GuardDaemonServer, generation: int | None) -> bool:
    """Check that startup still owns the service lifecycle generation."""

    with server._lifecycle_lock:
        return generation == server._lifecycle_generation and not server._shutdown_started.is_set()


def _failed_sqlite_identity(error: BaseException) -> tuple[int, int] | None:
    identity = getattr(error, "guard_failed_sqlite_identity", None)
    if isinstance(identity, tuple) and len(identity) == 2 and all(isinstance(part, int) for part in identity):
        return identity[0], identity[1]
    return None


def _begin_owned_service_with_store_recovery(
    server: GuardDaemonServer,
    generation: int,
    *,
    publish_before_workers: bool = False,
    continue_after_listen: bool = True,
) -> None:
    """Retry owned startup once after a fatal SQLite store is quarantined."""

    try:
        server._begin_owned_service(
            generation,
            publish_before_workers=publish_before_workers,
            continue_after_listen=continue_after_listen,
        )
    except sqlite3.DatabaseError as error:
        store = server._server.store
        if not store._recover_fatal_sqlite_store(
            error,
            failed_identity=_failed_sqlite_identity(error),
        ):
            raise
        server._begin_owned_service(
            generation,
            publish_before_workers=publish_before_workers,
            continue_after_listen=continue_after_listen,
        )


def _complete_owned_service_after_listen_with_store_recovery(
    server: GuardDaemonServer,
    generation: int,
) -> None:
    """Retry post-listen startup once after a fatal SQLite store is quarantined."""

    try:
        server._complete_owned_service_after_listen(generation)
    except sqlite3.DatabaseError as error:
        store = server._server.store
        if not store._recover_fatal_sqlite_store(
            error,
            failed_identity=_failed_sqlite_identity(error),
        ):
            raise
        server._complete_owned_service_after_listen(generation)


def _preflight_existing_service_workers(server: GuardDaemonServer) -> None:
    """Reject a restart while retained workers still need shutdown containment."""

    if server._aibom_refresh_thread is not None:
        if server._aibom_refresh_thread.is_alive():
            raise RuntimeError("AIBOM inventory refresh is still stopping")
        server._aibom_refresh_thread = None
    server._require_command_activity_maintenance_stopped()


def begin_service(server: GuardDaemonServer, *, publish_before_workers: bool = False) -> None:
    """Claim ownership and initialize background services for one generation."""

    from .manager import acquire_guard_daemon_owner_lock

    with server._finish_service_lock:
        with server._lifecycle_lock:
            server._lifecycle_generation += 1
            generation = server._lifecycle_generation
            server._active_start_generation = generation
        server._finish_service_completed = False
    server._record_lifecycle("start_requested")
    if server._is_quarantined():
        _preflight_existing_service_workers(server)
        raise RuntimeError("This Guard daemon is quarantined after unconfirmed containment.")
    try:
        with server._finish_service_lock:
            _preflight_existing_service_workers(server)
            with server._lifecycle_lock:
                if generation != server._lifecycle_generation:
                    raise RuntimeError("Guard daemon stopped during startup")
                server._shutdown_started.clear()
            if not startup_generation_is_current(server, generation):
                raise RuntimeError("Guard daemon stopped during startup")
            server._owner_lock = acquire_guard_daemon_owner_lock(server._server.store.guard_home)
            _begin_owned_service_with_store_recovery(
                server,
                generation,
                publish_before_workers=publish_before_workers,
                continue_after_listen=not publish_before_workers,
            )
        if publish_before_workers:
            _complete_owned_service_after_listen_with_store_recovery(server, generation)
    except BaseException as error:
        server._diagnostics.record_exception("daemon_start_failed")
        server._record_lifecycle("start_failed", reason="initialization_failed")
        serve_thread = server._thread
        leftover_serve_thread = None
        if serve_thread is not None:
            server._server.request_serve_stop()
            leftover_serve_thread = server._join_service_thread(
                serve_thread,
                deadline=time.monotonic() + 5,
            )
        if leftover_serve_thread is not None:
            add_note = getattr(error, "add_note", None)
            if callable(add_note):
                add_note("Guard retained daemon ownership because the serve thread did not exit.")
            raise
        if not server._finish_service():
            add_note = getattr(error, "add_note", None)
            if callable(add_note):
                add_note("Guard retained daemon ownership because partial-start containment was unconfirmed.")
        raise


def start_serve_thread(server: GuardDaemonServer, *, already_locked: bool = False) -> None:
    """Start the HTTP serve loop while holding the service ownership lock."""

    def start_locked() -> None:
        def run_serve() -> None:
            try:
                server._serve_forever()
            except BaseException as error:
                if server._serve_thread_error is None:
                    server._serve_thread_error = error
                if not isinstance(error, (KeyboardInterrupt, SystemExit)):
                    _LOGGER.exception("Guard daemon serve thread failed")

        if server._shutdown_started.is_set():
            raise RuntimeError("Guard daemon stopped during startup")
        if server._thread is not None and server._thread.is_alive():
            return
        server._serve_loop_started.clear()
        server._thread = threading.Thread(target=run_serve, daemon=True)
        server._thread.start()

    if already_locked:
        start_locked()
        return
    with server._finish_service_lock:
        start_locked()


def enable_full_capacity_for_generation(server: GuardDaemonServer, generation: int | None) -> None:
    """Enable workers only while the startup generation still owns the service."""

    with server._finish_service_lock:
        if not startup_generation_is_current(server, generation):
            raise RuntimeError("Guard daemon stopped during startup")
        server._server.hook_process_runner.enable_full_capacity()
        if not startup_generation_is_current(server, generation):
            raise RuntimeError("Guard daemon stopped during startup")


def contain_failed_service_start(
    server: GuardDaemonServer,
    error: BaseException,
    *,
    serve_thread_started: bool,
) -> None:
    """Contain partial startup state before propagating the original failure."""

    server._diagnostics.record_exception("daemon_start_thread_failed")
    serve_thread = server._thread
    serve_thread_contained = True
    if serve_thread_started and serve_thread is not None:
        server._server.request_serve_stop()
    else:
        try:
            server._server.server_close()
        except Exception:
            serve_thread_contained = False
    service_finished = server._finish_service()
    if serve_thread_started and serve_thread is not None:
        serve_thread_contained = (
            server._join_service_thread(
                serve_thread,
                deadline=time.monotonic() + 5,
            )
            is None
        )
    if serve_thread_contained and server._thread is serve_thread:
        server._thread = None
    if not service_finished or not serve_thread_contained:
        add_note = getattr(error, "add_note", None)
        if callable(add_note):
            add_note("Guard retained daemon ownership because startup containment was unconfirmed.")


__all__ = [
    "begin_service",
    "contain_failed_service_start",
    "enable_full_capacity_for_generation",
    "start_serve_thread",
    "startup_generation_is_current",
]

"""Daemon service shutdown and quarantine."""

from __future__ import annotations

from . import server as _server


def _finish_service(self: _server.GuardDaemonServer) -> bool:
    finish_lock = getattr(self, "_finish_service_lock", None)
    if finish_lock is None:
        with type(self)._quarantine_lock:
            finish_lock = getattr(self, "_finish_service_lock", None)
            if finish_lock is None:
                finish_lock = _server.threading.Lock()
                self._finish_service_lock = finish_lock
    with finish_lock:
        if getattr(self, "_finish_service_completed", False):
            return True
        contained = self._finish_service_locked()
        if contained:
            self._finish_service_completed = True
        return contained


def _finish_service_locked(self: _server.GuardDaemonServer) -> bool:
    self._owned_service_ready = False
    self._shutdown_started.set()
    contained = True
    stop_request_executors = getattr(self._server, "_stop_request_executors", None)
    if callable(stop_request_executors):
        try:
            contained = stop_request_executors() is not False and contained
        except Exception:
            contained = False
    stop_unclassified_watchdog = getattr(self._server, "stop_unclassified_watchdog", None)
    if callable(stop_unclassified_watchdog):
        try:
            contained = stop_unclassified_watchdog() is not False and contained
        except Exception:
            contained = False
    approval_attention = getattr(self._server, "approval_attention", None)
    if approval_attention is not None:
        try:
            contained = approval_attention.stop() is not False and contained
        except Exception:
            contained = False
    try:
        self._command_queue_worker = _server.stop_command_queue_worker(self._command_queue_worker)
        contained = self._command_queue_worker is None and contained
    except Exception:
        contained = False
    try:
        self._cloud_review_sync_worker = _server.stop_cloud_sync_sync_worker(self._cloud_review_sync_worker)
        contained = self._cloud_review_sync_worker is None and contained
    except Exception:
        contained = False
    runtime_heartbeat = getattr(self._server, "runtime_heartbeat", None)
    if runtime_heartbeat is not None:
        try:
            contained = runtime_heartbeat.stop(timeout_seconds=1.0) is not False and contained
        except Exception:
            contained = False
    runtime_hook_evidence_writer = getattr(self._server, "runtime_hook_evidence_writer", None)
    if runtime_hook_evidence_writer is not None:
        try:
            contained = runtime_hook_evidence_writer.stop(timeout_seconds=1.0) is not False and contained
        except Exception:
            contained = False
    hook_process_runner = getattr(self._server, "hook_process_runner", None)
    if hook_process_runner is not None:
        try:
            close_contained = getattr(hook_process_runner, "close_contained", None)
            if callable(close_contained):
                contained = close_contained() is not False and contained
            else:
                contained = hook_process_runner.close() is not False and contained
        except Exception:
            contained = False
    contained = self._join_service_background_threads() and contained
    with _server.suppress(Exception):
        _server.clear_guard_daemon_state_if_current(
            self._server.store.guard_home,
            pid=_server.os.getpid(),
            port=self.port,
        )
    with _server.suppress(Exception):
        self._server.store.clear_runtime_state(session_id=self._server.runtime_session_id)
    if contained and self._is_quarantined():
        try:
            self._server.server_close()
        except Exception:
            contained = False
    if contained:
        try:
            _server.release_guard_daemon_owner_lock(getattr(self, "_owner_lock", None))
        except Exception:
            contained = False
        else:
            self._owner_lock = None
    with _server.suppress(Exception):
        self._diagnostics.close(timeout_seconds=1.0)
    return self._record_quarantine_state(contained=contained)


def _join_service_thread(
    thread: _server.threading.Thread | None,
    *,
    deadline: float,
) -> _server.threading.Thread | None:
    if thread is None:
        return None
    if thread is not _server.threading.current_thread():
        thread.join(timeout=max(0.0, deadline - _server.time.monotonic()))
    return thread if thread.is_alive() else None


def _join_service_background_threads(self: _server.GuardDaemonServer) -> bool:
    deadline = _server.time.monotonic() + _server._AIBOM_REFRESH_STOP_JOIN_TIMEOUT_SECONDS
    self._watchdog_thread = self._join_service_thread(
        getattr(self, "_watchdog_thread", None),
        deadline=deadline,
    )
    self._bundle_refresh_thread = self._join_service_thread(
        getattr(self, "_bundle_refresh_thread", None),
        deadline=deadline,
    )
    self._aibom_refresh_thread = self._join_service_thread(
        getattr(self, "_aibom_refresh_thread", None),
        deadline=deadline,
    )
    self._extension_control_refresh_thread = self._join_service_thread(
        getattr(self, "_extension_control_refresh_thread", None),
        deadline=deadline,
    )
    self._headless_cloud_sync_thread = self._join_service_thread(
        getattr(self, "_headless_cloud_sync_thread", None),
        deadline=deadline,
    )
    self._command_activity_maintenance_thread = self._join_service_thread(
        getattr(self, "_command_activity_maintenance_thread", None),
        deadline=deadline,
    )
    return all(
        thread is None
        for thread in (
            self._watchdog_thread,
            self._bundle_refresh_thread,
            self._aibom_refresh_thread,
            self._extension_control_refresh_thread,
            self._headless_cloud_sync_thread,
            self._command_activity_maintenance_thread,
        )
    )


def _start_watchdog(self: _server.GuardDaemonServer) -> None:
    if self._watchdog_thread is not None and self._watchdog_thread.is_alive():
        return
    idle_timeout_seconds = self._server.idle_timeout_seconds
    if idle_timeout_seconds is None or idle_timeout_seconds <= 0:
        return
    self._watchdog_thread = _server.threading.Thread(target=self._watch_for_idle_shutdown, daemon=True)
    self._watchdog_thread.start()

"""Bounded request execution for the local Guard daemon."""

from __future__ import annotations

import queue
import socket
import threading
import time
from collections.abc import Callable
from typing import TypeAlias

_TransportWorkItem: TypeAlias = tuple[socket.socket, tuple[str, int]]


class BoundedRequestExecutor:
    def __init__(
        self,
        *,
        name: str,
        workers: int,
        queue_limit: int,
        run: Callable[[socket.socket, tuple[str, int]], None],
        discard: Callable[[socket.socket], None],
    ) -> None:
        self._queue: queue.Queue[_TransportWorkItem | None] = queue.Queue(maxsize=queue_limit)
        self._run = run
        self._discard = discard
        self._stopped = threading.Event()
        self._lifecycle_lock = threading.Lock()
        self._threads: list[threading.Thread] = []
        try:
            for index in range(workers):
                thread = threading.Thread(
                    target=self._worker,
                    daemon=True,
                    name=f"guard-http-{name}-{index + 1}",
                )
                thread.start()
                self._threads.append(thread)
        except BaseException:
            self._stopped.set()
            for _ in self._threads:
                self._queue.put(None, timeout=1.0)
            for thread in self._threads:
                thread.join(timeout=1.0)
            raise

    @property
    def threads(self) -> tuple[threading.Thread, ...]:
        return tuple(self._threads)

    def submit(self, request: socket.socket, client_address: tuple[str, int]) -> bool:
        with self._lifecycle_lock:
            if self._stopped.is_set():
                return False
            try:
                self._queue.put_nowait((request, client_address))
            except queue.Full:
                return False
        return True

    def shutdown(self, *, timeout_seconds: float) -> bool:
        with self._lifecycle_lock:
            if not self._stopped.is_set():
                self._stopped.set()
                while True:
                    try:
                        item = self._queue.get_nowait()
                    except queue.Empty:
                        break
                    if item is not None:
                        self._discard(item[0])
                    self._queue.task_done()
                for _ in self._threads:
                    self._queue.put_nowait(None)
        deadline = time.monotonic() + timeout_seconds
        for thread in self._threads:
            if thread is not threading.current_thread():
                thread.join(timeout=max(0.0, deadline - time.monotonic()))
        return all(not thread.is_alive() for thread in self._threads)

    def _worker(self) -> None:
        while True:
            item = self._queue.get()
            try:
                if item is None:
                    return
                self._run(*item)
            finally:
                self._queue.task_done()

"""Strict redacted native extension evidence and receipt binding validation."""

from __future__ import annotations

import hashlib
import json
import re
from typing import cast

_DIGEST = re.compile(r"[0-9a-f]{64}")
_CATALOG_ID = re.compile(r"command\.[a-z0-9]+(?:[.-][a-z0-9]+)*")
_VERSION = re.compile(r"[1-9][0-9]*\.[0-9]+\.[0-9]+")
_VARIANT = re.compile(r"[a-z0-9][a-z0-9_.:-]{0,255}")
_EXECUTABLE = re.compile(r"[A-Za-z0-9][A-Za-z0-9._+-]{0,127}")
_DETAIL = "Matched bounded structured command constraints."
_MAX_OBSERVATIONS = 2_048
_MAX_EVIDENCE = 8_192
_BINDING_FIELDS = frozenset(
    {
        "schema",
        "program_digest",
        "catalog_digest",
        "trust_digest",
        "control_revision",
        "managed_control_revision",
        "control_effective_digest",
        "observations_digest",
        "observation_count",
        "uncertainty_count",
    }
)
_OBSERVATION_FIELDS = frozenset(
    {
        "extension_id",
        "extension_version",
        "rule_id",
        "rule_version",
        "match_class",
        "match_classes",
        "matcher_evidence",
        "safe_variants",
        "uncertainty_reasons",
        "effective_segment_indexes",
    }
)


def _matches(value: object, pattern: re.Pattern[str], maximum: int) -> bool:
    return isinstance(value, str) and len(value) <= maximum and pattern.fullmatch(value) is not None


def _integer(value: object, maximum: int) -> bool:
    return type(value) is int and 0 <= value <= maximum


def valid_native_command_receipt_binding(value: object) -> bool:
    if not isinstance(value, dict) or set(value) != _BINDING_FIELDS:
        return False
    if value["schema"] != "guard.native-command-receipt-binding.v1":
        return False
    if any(
        not _matches(value[key], _DIGEST, 64)
        for key in (
            "program_digest",
            "catalog_digest",
            "trust_digest",
            "control_effective_digest",
            "observations_digest",
        )
    ):
        return False
    return (
        _integer(value["control_revision"], 2**64 - 1)
        and _integer(value["managed_control_revision"], 2**64 - 1)
        and _integer(value["observation_count"], _MAX_OBSERVATIONS)
        and _integer(value["uncertainty_count"], _MAX_OBSERVATIONS + 1)
    )


def _evidence_indexes(value: object, budget: list[int]) -> list[int] | None:
    if not isinstance(value, list) or len(value) > _MAX_EVIDENCE:
        return None
    budget[0] -= len(value)
    if budget[0] < 0:
        return None
    indexes: list[int] = []
    for item in value:
        if not isinstance(item, dict) or set(item) != {"segment_index", "executable", "detail"}:
            return None
        if not _integer(item["segment_index"], 127) or item["detail"] != _DETAIL:
            return None
        if item["executable"] is not None and not _matches(item["executable"], _EXECUTABLE, 128):
            return None
        indexes.append(cast(int, item["segment_index"]))
    return indexes


def _valid_observation(value: object, budget: list[int]) -> bool:
    if not isinstance(value, dict) or set(value) != _OBSERVATION_FIELDS:
        return False
    if any(not _matches(value[key], _CATALOG_ID, 256) for key in ("extension_id", "rule_id")):
        return False
    if not str(value["rule_id"]).startswith(f"{value['extension_id']}."):
        return False
    if any(not _matches(value[key], _VERSION, 64) for key in ("extension_version", "rule_version")):
        return False
    base = _evidence_indexes(value["matcher_evidence"], budget)
    variants = value["safe_variants"]
    uncertainty = value["uncertainty_reasons"]
    if base is None or not isinstance(variants, list) or len(variants) > 64:
        return False
    if uncertainty not in ([], ["matcher-failure"]):
        return False
    expected_classes = ["unsafe"] if base else []
    if uncertainty:
        expected_classes.append("uncertainty")
    if value["match_classes"] != expected_classes or value["match_class"] != (
        "uncertainty" if uncertainty else "unsafe"
    ):
        return False
    if not expected_classes or (not base and variants):
        return False
    variant_ids: set[str] = set()
    safe_indexes: set[int] = set()
    for variant in variants:
        if not isinstance(variant, dict) or set(variant) != {"match_class", "variant_id", "matcher_evidence"}:
            return False
        if variant["match_class"] != "safe-variant" or not _matches(variant["variant_id"], _VARIANT, 256):
            return False
        variant_id = cast(str, variant["variant_id"])
        if variant_id in variant_ids:
            return False
        variant_ids.add(variant_id)
        indexes = _evidence_indexes(variant["matcher_evidence"], budget)
        if not indexes:
            return False
        safe_indexes.update(indexes)
    effective = value["effective_segment_indexes"]
    if not isinstance(effective, list) or any(not _integer(index, 127) for index in effective):
        return False
    return effective == [index for index in base if index not in safe_indexes]


def _valid_permission_observation(value: object, budget: list[int]) -> bool:
    fields = {"extension_id", "permission_id", "matcher_evidence", "uncertainty_reasons"}
    if not isinstance(value, dict) or set(value) != fields:
        return False
    if not _matches(value["extension_id"], _CATALOG_ID, 256):
        return False
    permission_id = value["permission_id"]
    if not isinstance(permission_id, str) or len(permission_id) > 256:
        return False
    prefix = f"{value['extension_id']}.permission."
    if not permission_id.startswith(prefix) or not _matches(permission_id, _CATALOG_ID, 256):
        return False
    evidence = _evidence_indexes(value["matcher_evidence"], budget)
    uncertainty = value["uncertainty_reasons"]
    return evidence is not None and uncertainty in ([], ["matcher-failure"]) and bool(evidence or uncertainty)


def validate_native_command_observations(value: object) -> dict[str, object] | None:
    fields = {"schema", "binding", "observations", "permission_observations", "evaluation_error"}
    if not isinstance(value, dict) or set(value) != fields:
        return None
    if value["schema"] != "guard.native-command-observations.v1" or not valid_native_command_receipt_binding(
        value["binding"]
    ):
        return None
    observations = value["observations"]
    permission_observations = value["permission_observations"]
    error = value["evaluation_error"]
    if not isinstance(observations, list) or not isinstance(permission_observations, list):
        return None
    count = len(observations) + len(permission_observations)
    if count > _MAX_OBSERVATIONS:
        return None
    if error is not None and (error != "native_command_evaluation_failed" or count):
        return None
    budget = [_MAX_EVIDENCE]
    if not all(_valid_observation(observation, budget) for observation in observations):
        return None
    if not all(_valid_permission_observation(observation, budget) for observation in permission_observations):
        return None
    binding = cast(dict[str, object], value["binding"])
    typed_observations = cast(list[dict[str, object]], observations)
    typed_permissions = cast(list[dict[str, object]], permission_observations)
    if len({item["rule_id"] for item in typed_observations}) != len(typed_observations):
        return None
    if len({item["permission_id"] for item in typed_permissions}) != len(typed_permissions):
        return None
    uncertainty_count = sum(bool(item["uncertainty_reasons"]) for item in typed_observations + typed_permissions)
    uncertainty_count += error is not None
    if binding["observation_count"] != count or binding["uncertainty_count"] != uncertainty_count:
        return None
    canonical = json.dumps(
        {"observations": observations, "permission_observations": permission_observations, "evaluation_error": error},
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    expected = hashlib.sha256(b"hol-guard.native-command-observations.v1\0" + canonical).hexdigest()
    return cast(dict[str, object], value) if binding["observations_digest"] == expected else None

